     1	import Mathlib.Analysis.Calculus.Deriv.MeanValue
     2	
     3	namespace Research
     4	
     5	/-- The forward-difference approximation to the derivative of `f` at `x`
     6	with step `h`. -/
     7	noncomputable def forwardDifference (f : ℝ → ℝ) (x h : ℝ) : ℝ :=
     8	  (f (x + h) - f x) / h
     9	
    10	/-- A local bound on the variation of the prescribed interior derivative
    11	controls the forward-difference error. The value `D x` is a reference value;
    12	no derivative at either endpoint is assumed. -/
    13	theorem forwardDifference_error_bound
    14	    (f D : ℝ → ℝ) (x h L : ℝ)
    15	    (h_pos : 0 < h)
    16	    (L_nonneg : 0 ≤ L)
    17	    (f_continuous : ContinuousOn f (Set.Icc x (x + h)))
    18	    (f_derivative : ∀ t ∈ Set.Ioo x (x + h), HasDerivAt f (D t) t)
    19	    (derivative_variation :
    20	      ∀ t ∈ Set.Ioo x (x + h), |D t - D x| ≤ L * |t - x|) :
    21	    |forwardDifference f x h - D x| ≤ L * h := by
    22	  obtain ⟨c, hc, hslope⟩ :=
    23	    exists_hasDerivAt_eq_slope f D (by linarith : x < x + h)
    24	      f_continuous f_derivative
    25	  have hquotient : D c = forwardDifference f x h := by
    26	    simpa [forwardDifference] using hslope
    27	  have hdistance : |c - x| ≤ h := by
    28	    rw [abs_of_nonneg (sub_nonneg.mpr (le_of_lt hc.1))]
    29	    linarith [hc.2]
    30	  rw [← hquotient]
    31	  exact (derivative_variation c hc).trans (mul_le_mul_of_nonneg_left hdistance L_nonneg)
    32	
    33	end Research
